/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
a = np.load('source_pixels.npz')['rgb']
# Track bright cue ball via difference region; estimate center each frame via diff mask centroid vs previous
centers=[]
for f in range(0,96):
    if f==0:
        d = np.abs(a[1].astype(int)-a[0].astype(int)).sum(2)>30
    else:
        d = np.abs(a[f].astype(int)-a[max(0,f-1)].astype(int)).sum(2)>30
    ys,xs=np.where(d)
    if len(xs)>5:
        centers.append((f,round(xs.mean(),1),round(ys.mean(),1),len(xs)))
    else:
        centers.append((f,None,None,len(xs)))
for c in centers: print(c)
\""
